const VIDEO_ROLES={character:'Nhân vật',product:'Sản phẩm / đạo cụ',background:'Bối cảnh',storyboard:'Storyboard tổng thể'};
const CAMERAS={still:'Máy cố định, chỉ chủ thể chuyển động nhẹ.',push:'Máy tiến chậm, giữ phối cảnh ổn định.',pan:'Máy trượt ngang nhẹ, không tự chuyển cảnh.',orbit:'Máy di chuyển theo vòng cung nhỏ, không đổi bố cục chính.',pull:'Máy lùi chậm, mở rộng không gian, giữ chủ thể ổn định.',panRight:'Máy trượt sang phải, tốc độ đều, giữ đường chân trời.',tiltUp:'Máy nghiêng lên nhẹ từ thân lên mặt, không đổi danh tính.',tiltDown:'Máy nghiêng xuống nhẹ để nhấn sản phẩm hoặc trang phục.',low:'Góc thấp nhẹ hướng lên, chuyển máy chậm, giữ đúng tỷ lệ cơ thể.',high:'Góc cao nhẹ hướng xuống, không kéo méo hình học.',close:'Cận chi tiết chất liệu, tiến nhẹ, giữ đúng texture và màu.',handheld:'Máy cầm tay ổn định, dao động rất nhẹ có chủ đích, không rung giật.'};
function productionInstruction(d){return ['DỰNG VIDEO TỪ THAM CHIẾU CÓ PHÂN VAI.',d.storyMode==='whole'?'BASE là storyboard tổng thể: diễn giải các ô thành các cảnh nối tiếp theo thứ tự trái sang phải, trên xuống dưới. Không quay toàn tấm storyboard, không tạo video chia ô; chỉ một khung hình chuyển động tại mỗi thời điểm.':'BASE là ảnh khởi đầu của duy nhất cảnh '+(d.sceneIndex||1)+'. Bám bố cục, góc máy, hướng đầu và hướng mắt của khung này; không tự ép nhân vật nhìn camera. Không hiển thị bảng storyboard, đường chia ô, số thứ tự hay chú thích kỹ thuật, và không chuyển sang cảnh khác trong clip.', 'Nhân vật: giữ danh tính, tóc, vóc dáng và trang phục từ ref Nhân vật khi có; không lấy danh tính từ ref sản phẩm hoặc bối cảnh. Sản phẩm: giữ đúng hình học, tỷ lệ, nhãn, vật liệu và màu từ ref Sản phẩm; không tự thêm chữ/logo. Bối cảnh: theo ref Bối cảnh, khớp phối cảnh, ánh sáng và bóng tiếp xúc. Nếu không có ref cho một vai trò, giữ theo ảnh BASE. Storyboard tổng thể chỉ định trình tự và mạch hình ảnh, không được thay thế khóa nhận diện của các ref riêng. Nếu storyboard là bản phác thảo, dùng nó cho bố cục và hành động; hình dáng, màu và chất liệu lấy từ ref nhân vật/sản phẩm và mô tả chung, không biến video thành bản vẽ trừ khi được yêu cầu.', 'Các ảnh bổ sung cùng vai trò chỉ bổ sung đặc điểm tương thích; ảnh đầu tiên là chính. Không trộn mặt hoặc thêm người/vật thể ngoài yêu cầu.',CAMERAS[d.camera||'still'],d.textureLock!==false?'KHÓA CHẤT LIỆU: texture, độ nhám/độ bóng, lỗ chân lông, nếp vải, sợi tóc, phản xạ và màu sắc lấy từ ảnh gốc. Không làm đẹp/mịn da, không tái thiết kế vật liệu. Giữ chi tiết qua mọi frame; không tăng nét viền hay HDR giả.':'',d.pace==='slow'?'Nhịp chuyển động chậm, tăng/giảm tốc mềm, quán tính và trọng tâm tự nhiên.':d.pace==='dynamic'?'Nhịp chủ động vừa phải, chuyển động liên tục, không giật hoặc đổi tốc đột ngột.':'Nhịp tự nhiên, chuyển động liền mạch và ổn định.', 'NEGATIVE / TRÁNH: da nhựa, bề mặt sáp, airbrush, render 3D ngoài ý muốn, texture trôi, nhấp nháy, shimmer, oversharpen, halo, motion smear, méo mặt/tay, thừa ngón, thay danh tính, logo biến dạng, đổi trang phục, vật thể xuất hiện/mất, chuyển cảnh đột ngột, rung giật. '+(d.negativeText||''),d.motionLevel==='medium'?'Chuyển động vừa phải, trọng tâm và tương tác vật lý tự nhiên.':'Chuyển động tinh tế, chậm, giảm biến dạng tay, mặt và sản phẩm.', 'Giữ nhận diện, màu, quần áo, hướng sáng và quy mô không gian nhất quán giữa các cảnh. Tránh morphing, flicker, chi thể thừa, hình học cong vênh, chữ phát sinh, watermark mới. Không thay người chỉ để khớp dáng.'].filter(Boolean).join('\n')}
function videoRatio(width,height){if(!(width>0&&height>0))return '9:16';return ['9:16','16:9','1:1'].map(r=>({r,v:Math.abs(Math.log(width/height/(r.split(':')[0]/r.split(':')[1])))})).sort((a,b)=>a.v-b.v)[0].r}
function buildVideoProduction({mode='image',base,storyboard,frames=[],roles={},settings={},make,edge}){if(!['image','frames','whole'].includes(mode))throw Error('Chọn cách dựng video hợp lệ');if(![5,10].includes(Number(settings.duration||5)))throw Error('Mỗi cảnh hỗ trợ 5 hoặc 10 giây');const shots=mode==='frames'?frames.filter(f=>f.enabled!==false):[{tag:mode==='whole'?storyboard:base,label:mode==='whole'?'Storyboard tổng thể':'Ảnh khởi đầu',width:settings.width,height:settings.height,motion:settings.text}];if(!shots.length||shots.some(f=>!f.tag))throw Error('Chọn ảnh đầu vào và ít nhất một cảnh');const ratio=settings.ratio==='auto'||!settings.ratio?videoRatio(shots[0].width,shots[0].height):settings.ratio;if(!['9:16','16:9','1:1'].includes(ratio))throw Error('Tỉ lệ video không được hỗ trợ');if(!Object.hasOwn(CAMERAS,settings.camera||'still'))throw Error('Chuyển động máy không hợp lệ');const nodes=[],edges=[],sources=new Map(),source=(tag,label)=>{if(!sources.has(tag)){const n=make('source',0,sources.size*300,{refTag:tag,label});sources.set(tag,n);nodes.push(n)}return sources.get(tag)};const guides=Object.entries(roles).filter(([role])=>Object.hasOwn(VIDEO_ROLES,role)&&role!=='storyboard').flatMap(([role,tags])=>[...new Set(tags)].filter(Boolean).map(tag=>({role,tag})));if(settings.includeBoard&&mode==='frames'&&storyboard)guides.push({role:'storyboard',tag:storyboard});const videos=shots.map((shot,i)=>{const v=make('video',480,i*380,{videoProduction:true,storyMode:mode==='whole'?'whole':'frame',sceneIndex:i+1,sceneKey:shot.tag,ratio,duration:Number(settings.duration||5),camera:settings.camera||'still',motionLevel:settings.motionLevel||'subtle',textureLock:settings.textureLock!==false,pace:settings.pace||'natural',negativeText:String(settings.negativeText||'').slice(0,4000),text:[settings.text,mode==='frames'?shot.motion:''].filter(Boolean).join('\n')||'Tái hiện khung tham chiếu thành chuyển động tự nhiên.',label:'Cảnh '+String(i+1).padStart(2,'0')+' · '+(shot.label||'Video')});nodes.push(v);edges.push(edge(source(shot.tag,shot.label||'Khung '+(i+1)),v));for(const {role,tag}of guides){if(tag===shot.tag)continue;const e=edge(source(tag,VIDEO_ROLES[role]),v,'guide');e.data={...e.data,role};edges.push(e)}return v});let final=videos[0];if(videos.length>1&&settings.combine!==false){final=make('combine',950,0,{label:'Ghép '+videos.length+' cảnh',ratio,clipCount:videos.length});nodes.push(final);videos.forEach((v,i)=>edges.push(edge(v,final,'clip'+(i+1))))}const out=make('output',1380,0,{label:videos.length>1&&settings.combine!==false?'Video hoàn chỉnh':'Kết quả video'});nodes.push(out);edges.push(edge(final,out));return {reviewBeforeNext:false,nodes,edges,viewport:{x:60,y:70,zoom:.65},production:{mode,ratio,sceneCount:shots.length,estimatedSeconds:shots.length*Number(settings.duration||5)}}}
module.exports={VIDEO_ROLES,CAMERAS,productionInstruction,videoRatio,buildVideoProduction};
